"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# Check agent TOML developer_instructions sizes
$agentDir = "E:'"\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source\\agents\"
Get-ChildItem "'$agentDir -Filter "*.toml" | ForEach-Object {
  $content = Get-Content $_.FullName -Raw
  # Extract developer_instructions block
  if ($content -match '"'(?s)developer_instructions\\s*=\\s*\"\"\"(.*?)\"\"\"') {
    "'$instr = $matches[1]
    $bytes = [System.Text.Encoding]::UTF8.GetByteCount($instr)
    Write-Host "$($_.Name): developer_instructions = $bytes bytes (16KB default=16384, 64KB hard=65536)"
  } else {
    Write-Host "$($_.Name): no developer_instructions found"
  }
}'

