"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# Check if AGENTS.md references or includes global_working_agreement.md content
$agents = Get-Content "E:'"\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source\\AGENTS.md\" -Raw
"'$gwa = Get-Content "E:'"\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source\\config\\global_working_agreement.md\" -Raw

# Check for any significant text overlap - extract sentences
"'$agentSentences = ($agents -split "[.!?]'"\\s+\" | Where-Object { "'$_.Length -gt 60 })
$gwaSentences = ($gwa -split "[.!?]'"\\s+\" | Where-Object { "'$_.Length -gt 60 })

$duplicates = @()
foreach ($s in $agentSentences) {
    $trimmed = $s.Trim()
    if ($gwa.Contains($trimmed) -and $trimmed.Length -gt 80) {
        $duplicates += $trimmed
    }
}

if ($duplicates.Count -gt 0) {
    Write-Host "DUPLICATE content found ($($duplicates.Count) sentences):"
    $duplicates | Select-Object -First 5 | ForEach-Object { Write-Host "  [$($_.Substring(0, [Math]::Min(100,$_.Length)))]..." }
} else {
    Write-Host "No significant duplicate content between AGENTS.md and global_working_agreement.md"
}'

