"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# Check for recursive dump patterns in AGENTS.md and config files
# Look for things like "dump everything", "print all files", "recursive scan", embedded large data
$filesToCheck = @(
  "E:'"\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source\\AGENTS.md\",
  \"E:\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source\\config\\global_working_agreement.md\"
)

foreach ("'$f in $filesToCheck) {
  $content = Get-Content $f -Raw
  $patterns = @("recursive dump", "dump all", "print all", "cat -r", "find / ", "ls -R", "Get-ChildItem -Recurse", "read all files")
  Write-Host "=== $f ==="
  foreach ($p in $patterns) {
    if ($content -match [regex]::Escape($p)) {
      Write-Host "  FOUND pattern: $p"
    }
  }
  Write-Host "  (no forbidden patterns)" 
}'

